        padding = fill * (minimumwidth - len(sign) - len(body))
        if align == '>':
            return padding + sign + body
        elif align == '<':
            return sign + body + padding
        elif align == '^':
            half = len(padding) // 2
            return padding[:half] + sign + body + padding[half:]
