        return s
    return "'" + s.replace("'", '\'"\'"\'') + "'"

def _print_tokens(lexer):
    while (tt := lexer.get_token()):
        print('Token: ' + repr(tt))
if __name__ == '__main__':
    if len(sys.argv) == 1:
        _print_tokens(shlex())
    else:
        fn = sys.argv[1]
        with open(fn) as f:
            _print_tokens(shlex(f, fn))
